const GRADE_LABEL = { 1: "고1", 2: "고2", 3: "고3" };

const CATEGORY_ORDER = [
  "국어",
  "수학",
  "영어",
  "한국사",
  "사회탐구",
  "과학탐구",
  "직업탐구",
  "제2외국어·한문",
];

/** 학년(1|2|3)에 해당하는 과목을 카테고리별로 묶어서 반환한다. */
function getSubjectsForGrade(grade) {
  const label = GRADE_LABEL[grade];
  if (!label) return [];

  const grouped = new Map();
  for (const [category, g, code, name] of SUBJECTS) {
    if (g !== label) continue;
    if (!grouped.has(category)) grouped.set(category, []);
    grouped.get(category).push({ code, name });
  }

  return CATEGORY_ORDER.filter((c) => grouped.has(c)).map((category) => ({
    category,
    subjects: grouped.get(category),
  }));
}
